// Doubles as their two words, high first: JavaScript's arithmetic, rounded to nearest even, with no branch.
// c is 1 or 0: x where it is 1, y where 0.
uvec2 sel(uint c, uvec2 x, uvec2 y) {
  uvec2 m = uvec2(0u - c);
  return (x & m) | (y & ~m);
}
int seli(uint c, int x, int y) { return int((uint(x) & (0u - c)) | (uint(y) & ~(0u - c))); }
uvec2 add64(uvec2 a, uvec2 b) {
  uint lo = a.y + b.y;
  return uvec2(a.x + b.x + uint(lo < a.y), lo);
}
uvec2 sub64(uvec2 a, uvec2 b) { return uvec2(a.x - b.x - uint(a.y < b.y), a.y - b.y); }
uint lt64(uvec2 a, uvec2 b) { return uint(a.x < b.x) | (uint(a.x == b.x) & uint(a.y < b.y)); }
// by n bits, 0 from 64 up
uvec2 shl64(uvec2 a, int n) {
  uint s = uint(n) & 31u;
  uvec2 low = uvec2((a.x << s) | ((a.y >> 1) >> (31u - s)), a.y << s);
  return sel(uint(n < 32), low, sel(uint(n < 64), uvec2(a.y << s, 0u), uvec2(0u)));
}
uvec2 shr64(uvec2 a, int n) {
  uint s = uint(n) & 31u;
  uvec2 low = uvec2(a.x >> s, (a.y >> s) | ((a.x << 1) << (31u - s)));
  return sel(uint(n < 32), low, sel(uint(n < 64), uvec2(0u, a.x >> s), uvec2(0u)));
}
// shifted right, any 1 shifted out kept in bit 0
uvec2 shrSticky(uvec2 a, int n) {
  uvec2 r = shr64(a, n);
  return uvec2(r.x, r.y | uint(shl64(r, n) != a));
}
int clz32(uint x) {
  uint n = 0u, c;
  c = uint(x <= 0xffffu); n += c * 16u; x <<= c * 16u;
  c = uint(x <= 0xffffffu); n += c * 8u; x <<= c * 8u;
  c = uint(x <= 0xfffffffu); n += c * 4u; x <<= c * 4u;
  c = uint(x <= 0x3fffffffu); n += c * 2u; x <<= c * 2u;
  c = uint(x <= 0x7fffffffu); n += c; x <<= c;
  return int(n + uint(x == 0u));
}
int clz64(uvec2 a) { return seli(uint(a.x != 0u), clz32(a.x), 32 + clz32(a.y)); }
// a 32 by 32 bit product, 64 bits
uvec2 mul32(uint a, uint b) {
  uint a0 = a & 0xffffu, a1 = a >> 16, b0 = b & 0xffffu, b1 = b >> 16;
  uint p00 = a0 * b0, p01 = a0 * b1, p10 = a1 * b0, p11 = a1 * b1;
  uint mid = (p00 >> 16) + (p01 & 0xffffu) + (p10 & 0xffffu);
  return uvec2(p11 + (p01 >> 16) + (p10 >> 16) + (mid >> 16), (p00 & 0xffffu) | (mid << 16));
}

const uvec2 D_ZERO = uvec2(0u);
const uvec2 D_ONE = uvec2(0x3ff00000u, 0u);
bool dZero(uvec2 a) { return ((a.x << 1) | a.y) == 0u; }
uint dSign(uvec2 a) { return a.x >> 31; }
int dExp(uvec2 a) { return int((a.x >> 20) & 0x7ffu); }
// the significand, its leading 1 at bit 52
uvec2 dMant(uvec2 a) { return uvec2((a.x & 0xfffffu) | 0x100000u, a.y); }
uvec2 dNeg(uvec2 a) { return uvec2(a.x ^ 0x80000000u, a.y); }
uvec2 dAbs(uvec2 a) { return uvec2(a.x & 0x7fffffffu, a.y); }
// a significand whose leading 1 is at bit 62, 10 bits below the 53 kept and a sticky 1 in bit 0, to nearest even
uvec2 dRound(uint sign, int e, uvec2 m) {
  uint rest = m.y & 0x3ffu;
  m = shr64(m, 10);
  m = add64(m, uvec2(0u, uint(rest > 0x200u) | (uint(rest == 0x200u) & m.y & 1u)));
  uint over = (m.x >> 21) & 1u;
  m = shr64(m, int(over));
  return uvec2((sign << 31) | (uint(e + int(over)) << 20) | (m.x & 0xfffffu), m.y);
}
// a significand that is not 0, of any width, its exponent e for a leading 1 at bit 62, to nearest even
uvec2 dNormal(uint sign, int e, uvec2 m) {
  int z = clz64(m);
  uint top = uint(z == 0);
  int up = max(z - 1, 0);
  return dRound(sign, e + int(top) - up, sel(top, shrSticky(m, 1), shl64(m, up)));
}
uvec2 dAdd(uvec2 a, uvec2 b) {
  uint swap = lt64(dAbs(a), dAbs(b));
  uvec2 x = sel(swap, b, a), y = sel(swap, a, b);
  int ex = dExp(x);
  uvec2 mx = shl64(dMant(x), 10);
  uvec2 my = sel(uint(dZero(y)), D_ZERO, shrSticky(shl64(dMant(y), 10), ex - dExp(y)));
  uvec2 m = sel(uint(dSign(x) == dSign(y)), add64(mx, my), sub64(mx, my));
  uint cancel = uint(m == D_ZERO);
  uvec2 r = sel(cancel, D_ZERO, dNormal(dSign(x), ex, sel(cancel, D_ONE, m)));
  return sel(uint(dZero(x)), uvec2(a.x & b.x & 0x80000000u, 0u), r);
}
uvec2 dMul(uvec2 a, uvec2 b) {
  uint sign = dSign(a) ^ dSign(b);
  uvec2 ma = dMant(a), mb = dMant(b);
  // the 106-bit product: the 64 bits from its leading 1 down, the rest kept as a sticky bit
  uvec2 ll = mul32(ma.y, mb.y), mid = add64(mul32(ma.y, mb.x), mul32(ma.x, mb.y));
  uint w1 = ll.x + mid.y;
  uvec2 top = add64(add64(mul32(ma.x, mb.x), uvec2(0u, mid.x)), uvec2(0u, uint(w1 < ll.x)));
  uint high = (top.x >> 9) & 1u;
  int shift = 42 + int(high);
  uvec2 m = shl64(top, 64 - shift);
  m.y |= (w1 >> uint(shift - 32)) | uint(((w1 << uint(64 - shift)) | ll.y) != 0u);
  uvec2 r = dRound(sign, dExp(a) + dExp(b) - 1023 + int(high), m);
  return sel(uint(dZero(a)) | uint(dZero(b)), uvec2(sign << 31, 0u), r);
}
uvec2 dDiv(uvec2 a, uvec2 b) {
  uint sign = dSign(a) ^ dSign(b);
  uvec2 r = dMant(a), d = dMant(b);
  uint less = lt64(r, d);
  r = shl64(r, int(less));
  uvec2 q = D_ZERO;
  for (int i = 0; i < 55; i++) {
    uint fits = 1u - lt64(r, d);
    r = shl64(sel(fits, sub64(r, d), r), 1);
    q = shl64(q, 1) | uvec2(0u, fits);
  }
  q = shl64(q, 8) | uvec2(0u, uint(r != D_ZERO));
  return sel(uint(dZero(a)), uvec2(sign << 31, 0u), dRound(sign, dExp(a) - dExp(b) + 1023 - int(less), q));
}
bool dLt(uvec2 a, uvec2 b) {
  uint both = uint(dZero(a)) & uint(dZero(b));
  uint sa = dSign(a), sb = dSign(b);
  uint same = sel(sa, uvec2(lt64(b, a)), uvec2(lt64(a, b))).x;
  return ((1u - both) & sel(uint(sa != sb), uvec2(sa), uvec2(same)).x) == 1u;
}
// toward zero
uvec2 dTrunc(uvec2 a) {
  int e = dExp(a) - 1023;
  return sel(uint(e < 0), uvec2(a.x & 0x80000000u, 0u), a & ~shr64(uvec2(0xfffffu, 0xffffffffu), max(e, 0)));
}
uvec2 dFromInt(int i) {
  return sel(uint(i == 0), D_ZERO, dNormal(uint(i < 0), 1053, uvec2(max(uint(abs(i)), 1u), 0u)));
}
uvec2 dFromFloat(float f) {
  uint b = floatBitsToUint(f);
  uvec2 d = uvec2((b & 0x80000000u) | ((((b >> 23) & 0xffu) + 896u) << 20) | ((b & 0x7fffffu) >> 3), b << 29);
  return sel(uint((b << 1) == 0u), uvec2(b, 0u), d);
}
// the float nearest, ties to even, as a Float32Array keeps it
float dToFloat(uvec2 a) {
  uvec2 m = shl64(dMant(a), 10);
  uint kept = m.x >> 7, rest = m.x & 0x7fu;
  kept += uint(rest > 0x40u) | (uint(rest == 0x40u) & (uint(m.y != 0u) | (kept & 1u)));
  uint over = kept >> 24;
  uint bits = (dSign(a) << 31) | (uint(dExp(a) - 896 + int(over)) << 23) | ((kept >> over) & 0x7fffffu);
  return uintBitsToFloat(sel(uint(dZero(a)), a, uvec2(bits)).x);
}
// toward zero, for |a| under 2^31
int dToInt(uvec2 a) {
  int e = dExp(a) - 1023;
  int v = int(shr64(dMant(a), clamp(52 - e, 0, 64)).y);
  return seli(uint(e < 0), 0, seli(dSign(a), -v, v));
}
// a positive number times 10^digits, rounded half up exactly as toFixed rounds it: the whole number toFixed writes
uvec2 dDecimal(uvec2 a, int digits) {
  uint m = digits == 3 ? 1000u : digits == 2 ? 100u : 10u;
  uvec2 v = dMant(a);
  uvec2 lo = mul32(v.y, m);
  uvec2 p = uvec2(v.x * m + lo.x, lo.y);
  int shift = 52 - (dExp(a) - 1023);
  uvec2 n = shr64(add64(p, shl64(uvec2(0u, 1u), shift - 1)), shift);
  return sel(uint(dZero(a)), D_ZERO, dFromInt(int(n.y)));
}

// Pairs of floats, hi + lo (about 48 bits), for the numbers worked out from the clock: each rounds to the float the
// player's double rounds to. Each sum and product keeps its rounding error, which a compiler that rearranges the steps
// would drop ((a + b) - a is b only in exact numbers): keep() passes a float through an integer XOR with a 0 the
// compiler cannot see (iResolution.z is 1.0), so no step is moved, fused or cancelled across it. Every step is guarded:
// with the sums and the product's split alone, an NVIDIA RTX's compiler cancelled enough to put a dozen of the silk's
// floats one apart from the player's.
float keep(float x) { return uintBitsToFloat(floatBitsToUint(x) ^ (uint(iResolution.z) - 1u)); }
vec2 twoSum(float a, float b) {
  float s = keep(a + b);
  float v = keep(s - a);
  return vec2(s, keep(keep(a - keep(s - v)) + keep(b - v)));
}
vec2 quickSum(float a, float b) {
  float s = keep(a + b);
  return vec2(s, keep(b - keep(s - a)));
}
vec2 twoProd(float a, float b) {
  float p = keep(a * b);
  float ta = keep(4097.0 * a);
  float ah = keep(ta - keep(ta - a));
  float al = keep(a - ah);
  float tb = keep(4097.0 * b);
  float bh = keep(tb - keep(tb - b));
  float bl = keep(b - bh);
  return vec2(p, keep(keep(keep(keep(ah * bh - p) + keep(ah * bl)) + keep(al * bh)) + keep(al * bl)));
}
vec2 pf(float a) { return vec2(a, 0.0); }
vec2 pAdd(vec2 a, vec2 b) {
  vec2 s = twoSum(a.x, b.x);
  vec2 t = twoSum(a.y, b.y);
  s = quickSum(s.x, s.y + t.x);
  return quickSum(s.x, s.y + t.y);
}
vec2 pSub(vec2 a, vec2 b) { return pAdd(a, -b); }
vec2 pMul(vec2 a, vec2 b) {
  vec2 p = twoProd(a.x, b.x);
  return quickSum(p.x, p.y + (a.x * b.y + a.y * b.x));
}
vec2 pDiv(vec2 a, vec2 b) {
  float q1 = keep(a.x / b.x);
  vec2 r = pSub(a, pMul(b, pf(q1)));
  float q2 = keep(r.x / b.x);
  r = pSub(r, pMul(b, pf(q2)));
  return pAdd(quickSum(q1, q2), pf(keep(r.x / b.x)));
}
vec2 pSqrt(vec2 a) {
  if (a.x <= 0.0) return vec2(0.0);
  float x = keep(sqrt(a.x));
  vec2 r = pSub(a, twoProd(x, x));
  return quickSum(x, r.x / (2.0 * x));
}
bool pLess(vec2 a, vec2 b) { return a.x < b.x || (a.x == b.x && a.y < b.y); }
vec2 pMin(vec2 a, vec2 b) { return pLess(b, a) ? b : a; }
vec2 pMax(vec2 a, vec2 b) { return pLess(a, b) ? b : a; }
vec2 pAbs(vec2 a) { return a.x < 0.0 ? -a : a; }
vec2 pFloor(vec2 a) {
  float f = floor(a.x);
  return f == a.x ? quickSum(f, floor(a.y)) : pf(f);
}
// JavaScript's Math.round: the nearest whole number, halves up
vec2 pRound(vec2 a) { return pFloor(pAdd(a, pf(0.5))); }
// a double as a pair
vec2 pOf(uvec2 d) {
  float hi = dToFloat(d);
  return vec2(hi, dToFloat(dAdd(d, dNeg(dFromFloat(hi)))));
}

const vec2 P_LN2 = vec2(0.6931472, -1.9046542e-9);
const vec2 P_HALF_PI = vec2(1.5707964, -4.371139e-8);
const vec2 EXP_C[11] = vec2[](
  vec2(1.0, 0.0), vec2(1.0, 0.0),
  vec2(0.5, 0.0), vec2(0.16666667, -4.967054e-9),
  vec2(0.041666668, -1.2417635e-9), vec2(0.008333334, -4.346172e-10),
  vec2(0.0013888889, -3.3631094e-11), vec2(0.0001984127, -2.7255969e-12),
  vec2(0.000024801588, -3.406996e-13), vec2(0.0000027557319, 3.7935712e-14),
  vec2(2.755732e-7, -7.575112e-15)
);
// e^a = 2^k (e^(r / 16))^16, r = a - k ln 2
vec2 pExp(vec2 a) {
  float k = floor(a.x / P_LN2.x + 0.5);
  vec2 r = pSub(a, pMul(P_LN2, pf(k))) * 0.0625;
  vec2 s = EXP_C[10];
  for (int i = 9; i >= 0; i--) s = pAdd(pMul(s, r), EXP_C[i]);
  for (int i = 0; i < 4; i++) s = pMul(s, s);
  return s * uintBitsToFloat(uint(int(k) + 127) << 23);
}
// a Newton step on e^y = a from the float's own log, whose error it squares, to within a pair's
vec2 pLog(vec2 a) {
  vec2 y = pf(keep(log(a.x)));
  return pAdd(y, pSub(pMul(a, pExp(-y)), pf(1.0)));
}
const vec2 SIN_C[9] = vec2[](
  vec2(1.0, 0.0), vec2(-0.16666667, 4.967054e-9),
  vec2(0.008333334, -4.346172e-10), vec2(-0.0001984127, 2.7255969e-12),
  vec2(0.0000027557319, 3.7935712e-14), vec2(-2.5052108e-8, -4.417623e-16),
  vec2(1.6059044e-10, -5.3525265e-18), vec2(-7.6471636e-13, -1.22007105e-20),
  vec2(2.8114574e-15, -1.0462085e-22)
);
const vec2 COS_C[10] = vec2[](
  vec2(1.0, 0.0), vec2(-0.5, 0.0),
  vec2(0.041666668, -1.2417635e-9), vec2(-0.0013888889, 3.3631094e-11),
  vec2(0.000024801588, -3.406996e-13), vec2(-2.755732e-7, 7.575112e-15),
  vec2(2.0876756e-9, 1.108284e-16), vec2(-1.1470745e-11, -2.3722077e-19),
  vec2(4.7794773e-14, 7.625444e-22), vec2(-1.5619207e-16, -1.5404471e-24)
);
// the sine and the cosine: hi and lo of each
vec4 pSinCos(vec2 a) {
  float k = floor(a.x / P_HALF_PI.x + 0.5);
  vec2 r = pSub(a, pMul(P_HALF_PI, pf(k)));
  vec2 rr = pMul(r, r);
  vec2 s = SIN_C[8];
  for (int i = 7; i >= 0; i--) s = pAdd(pMul(s, rr), SIN_C[i]);
  s = pMul(s, r);
  vec2 c = COS_C[9];
  for (int i = 8; i >= 0; i--) c = pAdd(pMul(c, rr), COS_C[i]);
  int q = int(k) & 3;
  return q == 0 ? vec4(s, c) : q == 1 ? vec4(c, -s) : q == 2 ? vec4(-s, -c) : vec4(-c, s);
}

// The clock's program: its constants and its instructions: an operation, a target, a and b, five and nine bits each.
const uvec2 CPOOL[14] = uvec2[](
  uvec2(0x00000000u, 0x00000000u), uvec2(0x4010aaaau, 0xaaaaaaabu), uvec2(0x408f4000u, 0x00000000u),
  uvec2(0x40590000u, 0x00000000u), uvec2(0x40100000u, 0x00000000u), uvec2(0x3fc99999u, 0x9999999au),
  uvec2(0x3fb99999u, 0x9999999au), uvec2(0x3ff00000u, 0x00000000u), uvec2(0x40080000u, 0x00000000u),
  uvec2(0x40000000u, 0x00000000u), uvec2(0x80000000u, 0x00000000u), uvec2(0x405e0000u, 0x00000000u),
  uvec2(0x400364c2u, 0xf837b4a2u), uvec2(0xbfb52926u, 0xf5cfa400u)
);
const uint CCODE[85] = uint[](
  0x050404a0u, 0x078384aau, 0x050404c0u, 0x010044cau, 0x130944c5u, 0x018644a6u, 0x018684e6u, 0x0d808506u,
  0x028a0525u, 0x14810527u, 0x148a0521u, 0x0a898541u, 0x010a8546u, 0x05044560u, 0x1500056au, 0x15818567u,
  0x12800549u, 0x15850580u, 0x1609c587u, 0x138005a9u, 0x138b04e6u, 0x050b45a0u, 0x0389c5aau, 0x128ac4a5u,
  0x168944a5u, 0x168944a5u, 0x168245a5u, 0x168205a1u, 0x168945a5u, 0x0881c4a1u, 0x050a8560u, 0x0009456au,
  0x1684c5a0u, 0x050ac560u, 0x098b456au, 0x050ac380u, 0x050445a0u, 0x160505aau, 0x050a8540u, 0x000b454au,
  0x050a83a0u, 0x050983c0u, 0x0c0ac549u, 0x158605a9u, 0x168a85a8u, 0x0b098541u, 0x148a8529u, 0x1481c521u,
  0x0505c580u, 0x038a458au, 0x14024525u, 0x150a4549u, 0x14058500u, 0x050a8540u, 0x1409854au, 0x0505c500u,
  0x130a850au, 0x050484c0u, 0x168004cau, 0x050b45a0u, 0x000b05aau, 0x05048540u, 0x1681c54au, 0x050b0580u,
  0x0b0a058au, 0x05098500u, 0x0b0b050au, 0x050a03e0u, 0x050984c0u, 0x0b81c4cau, 0x05098400u, 0x050a84c0u,
  0x0c0ac4cau, 0x05098420u, 0x050a8440u, 0x05884546u, 0x058844c6u, 0x000984c3u, 0x130a84c1u, 0x13030545u,
  0x000a854bu, 0x050a8460u, 0x130344c5u, 0x000984cbu, 0x05098480u
);

// Buffer A's first row keeps the state: its mark, the text's scene and the canvas in texel 0; the settings' signature
// and the clock's flags (whether this frame draws, whether the pace has begun) in texel 1; then the clock's doubles,
// each as four 16-bit pieces in a texel of its own.
const int T_MARK = 0;
const int T_FLAGS = 1;
const int T_CLOCK = 2;
vec4 state(sampler2D a, int i) { return texelFetch(a, ivec2(i, 0), 0); }
uvec2 readDouble(sampler2D a, int i) {
  vec4 v = state(a, i);
  return uvec2((uint(v.x) << 16) | uint(v.y), (uint(v.z) << 16) | uint(v.w));
}
vec4 pieces(uvec2 d) { return vec4(d.x >> 16, d.x & 0xffffu, d.y >> 16, d.y & 0xffffu); }
// n as a count no compiler can see (iResolution.z is 1), so it keeps a long loop a loop rather than writing its body
// out step by step
int steps(int n) { return n * int(iResolution.z); }
uvec2 hundredths(float x) { return dFromInt(int(floor(max(x, 0.0) * 100.0 + 0.5))); }
const float MAGIC = 4103.5;   // the state's mark, which no half float holds
const float SCENE = 16653099.0;   // this text's scene, beside the mark
const int T_BOX = 7;     // the canvas and the flower's scale, uBox and uS, and the outermost petal
const int T_GROUP = 8;   // uGroup at the time drawn: the loop's zoom (its log) and turn
const int STATE = 9;

// Common's settings as one number, in two 16-bit halves
vec2 signature() {
  uint h = 2166136261u;
  for (int k = 0; k < 3; k++) h = (h ^ floatBitsToUint(k == 0 ? SPEED : k == 1 ? FPS : EASE)) * 16777619u;
  return vec2(h >> 16, h & 0xffffu);
}

// The players' tick on Shadertoy's time, from the state the frame before left: the clock's doubles, whether this frame
// draws, whether the pace has begun, and the loop's zoom and turn at the time drawn.
struct Tick { uvec2 d[5]; bool draw; bool paceSet; vec2 group; };
Tick tick(sampler2D a, bool fresh, bool kept) {
  float x = iTime * 240.0, grid = floor(x + 0.5);
  uvec2 CR[46];
  for (int n = 0; n < 14; n++) CR[n] = CPOOL[n];
  CR[14] = dFromInt(int(grid));
  CR[15] = dFromFloat(iTime);
  CR[16] = abs(x - grid) <= max(1e-4, grid * 2.4e-7) ? D_ONE : D_ZERO;
  CR[17] = fresh ? D_ONE : D_ZERO;
  CR[18] = kept ? D_ZERO : D_ONE;
  CR[19] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 0);
  CR[20] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 1);
  CR[21] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 2);
  CR[22] = fresh ? D_ZERO : readDouble(a, T_CLOCK + 3);
  CR[24] = fresh ? dNeg(D_ONE) : readDouble(a, T_CLOCK + 4);
  CR[23] = !fresh && state(a, T_FLAGS).w != 0.0 ? D_ONE : D_ZERO;
  CR[25] = hundredths(SPEED);
  CR[26] = hundredths(EASE);
  CR[27] = dFromInt(clamp(int(floor(FPS + 0.5)), 1, 120));
  for (int pc = 0; pc < steps(85); pc++) {
    uint ins = CCODE[pc];
    uint op = ins & 31u;
    int d = int((ins >> 5) & 511u);
    uvec2 a = CR[int((ins >> 14) & 511u)], b = CR[int(ins >> 23)], r;
    if (op <= 4u) {
      // add, sub, trunc, floor, ceil: one addition, of the integer toward zero and a step where one is due
      uvec2 t = dTrunc(a);
      bool whole = op >= 2u;
      bool step = t != a && ((op == 3u && dSign(a) == 1u) || (op == 4u && dSign(a) == 0u));
      uvec2 y = whole ? (step ? (op == 3u ? dNeg(D_ONE) : D_ONE) : uvec2(0x80000000u, 0u)) : op == 1u ? dNeg(b) : b;
      r = dAdd(whole ? t : a, y);
    }
    else if (op == 5u) r = dMul(a, b);
    else if (op == 6u) r = dDiv(a, b);
    else if (op <= 9u) {
      bool less = dLt(a, b);
      r = op == 7u ? (dLt(b, a) ? b : a) : op == 8u ? (less ? b : a) : (less ? D_ONE : D_ZERO);
    }
    else if (op == 10u) r = dZero(CR[d]) ? b : a;
    else r = dFromFloat(dToFloat(a));
    CR[d] = r;
  }
  Tick k;
  k.d[0] = CR[28];
  k.d[1] = CR[29];
  k.d[2] = CR[30];
  k.d[3] = CR[31];
  k.d[4] = CR[33];
  k.draw = !dZero(CR[34]);
  k.paceSet = !dZero(CR[32]);
  k.group = vec2(dToFloat(CR[35]), dToFloat(CR[36]));
  return k;
}

// The outermost petal any time of the loop shows in a canvas of W by H pixels at scale S, as rosette.ts's
// rosettePetals finds it: from the last whose nearest point could lie in the box's corner, inward, the first whose
// circle of reach about its anchor meets the box at one of the loop's times.
bool inBox(vec2 r, vec2 th) {
  vec4 sc = pSinCos(th);
  vec2 gx = pMax(pf(0.0), pSub(pAbs(pMul(r, sc.zw)), pf(iResolution.x * 0.5)));
  vec2 gy = pMax(pf(0.0), pSub(pAbs(pMul(r, sc.xy)), pf(iResolution.y * 0.5)));
  vec2 reach = pAdd(pMul(r, REACH), pf(4.0));
  return !pLess(pMul(reach, reach), pAdd(pMul(gx, gx), pMul(gy, gy)));
}
float outermost(vec2 S) {
  vec2 W = pf(iResolution.x);
  vec2 H = pf(iResolution.y);
  vec2 corner = pDiv(pMul(pSqrt(pAdd(pMul(W, W), pMul(H, H))), pf(0.5)), S);
  float n = pFloor(pDiv(pLog(pDiv(corner, NEAR)), K)).x + 1.0;
  for (int i = 0; i < steps(512); i++) {
    if (n <= float(INNERMOST)) break;
    vec2 r = pMul(S, pExp(pMul(K, pf(n))));
    vec2 th = pAdd(pMul(ALPHA, pf(n)), TURN0);
    for (int s = 0; s <= 24; s++)
      if (inBox(pMul(r, ZOOM_AT[s]), pAdd(th, TURN_AT[s]))) return n;
    n -= 1.0;
  }
  return float(INNERMOST);
}

// ==== Buffer A ==== iChannel0: Buffer A (filter: nearest, wrap: clamp)
// The state, in the first row: the mark, the settings' signature and the clock's flags, the clock's doubles, the
// canvas's scale and outermost petal (kept while the canvas and the settings are), and the loop's zoom and turn at the
// time drawn.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  ivec2 p = ivec2(fragCoord);
  if (p.y != 0 || p.x >= STATE) discard;
  int i = p.x;
  // the state is this text's, from an earlier frame of this run, for this canvas and these settings
  vec4 mark = state(iChannel0, T_MARK);
  bool fresh = iFrame == 0 || mark.xy != vec2(MAGIC, SCENE);
  vec2 sign = signature();
  bool kept = !fresh && mark.zw == iResolution.xy && state(iChannel0, T_FLAGS).xy == sign;
  if (i == T_MARK) fragColor = vec4(MAGIC, SCENE, iResolution.xy);
  else if (i < T_BOX || i == T_GROUP) {
    // every frame: the clock, and the loop's zoom and turn at the time drawn
    Tick k = tick(iChannel0, fresh, kept);
    if (i == T_FLAGS) fragColor = vec4(sign, k.draw ? 1.0 : 0.0, k.paceSet ? 1.0 : 0.0);
    else if (i == T_GROUP) fragColor = vec4(k.group, 0.0, 0.0);
    else fragColor = pieces(k.d[i - T_CLOCK]);
  } else if (kept) fragColor = state(iChannel0, i);
  else {
    // the scale, as the player's float holds the double, and the outermost petal
    uvec2 S = dMul(SPAN_D, dFromFloat(max(iResolution.x, iResolution.y)));
    fragColor = vec4(iResolution.xy, dToFloat(S), outermost(pOf(S)));
  }
}

// ==== Buffer B ==== iChannel0: Buffer A (filter: nearest, wrap: clamp); iChannel1: Buffer B (filter: nearest, wrap: clamp)
// The frame: the player's fragment shader as it is, its uniforms from Buffer A; between the frames the pace draws, the
// frame drawn last. A finish (a soft blur, a grain) would take it from here.
vec4 fragPlace;
vec2 uBox;            // the canvas, px
float uS;             // its half-diagonal, px
float uK;             // log radius a petal grows by
float uAlpha;         // turn a petal (radians, y down), signed by the hand
float uTurn0;         // the flower's turn at the loop's start
vec2 uGroup;          // the loop's zoom (log) and turn now
float uEk;            // e^(-k): the radius ratio's step from one petal to the next out
ivec2 uRange;         // the petals drawn, innermost and outermost index
vec4 uLens;           // x0, x1, half-width w, the arcs' radius rho
vec2 uLensMid;        // the lens's middle xm and its arcs' centres' offset d
float uAngMax;        // the most a petal reaches round from its anchor's direction
vec4 uGrad;           // the gradient's middle (cu, cv) and radii (ru, rv) in the lens's box
vec4 uStopAt;         // the stops' offsets
int uFlow;
int uPhase;
vec3 uGround;
vec3 uHeart;
vec2 uHeartR;         // the glow's opaque middle and its end, shares of S
vec4 o;

const float TAU = 6.28318530718;

vec3 stopColor(int key, float g) {
  int b = key * 4;
  if (g <= uStopAt.x) return uStop[b];
  if (g <= uStopAt.y) return mix(uStop[b], uStop[b + 1], (g - uStopAt.x) / (uStopAt.y - uStopAt.x));
  if (g <= uStopAt.z) return mix(uStop[b + 1], uStop[b + 2], (g - uStopAt.y) / (uStopAt.z - uStopAt.y));
  if (g <= uStopAt.w) return mix(uStop[b + 2], uStop[b + 3], (g - uStopAt.z) / (uStopAt.w - uStopAt.z));
  return uStop[b + 3];
}

float heartAlpha(float x) {
  if (x <= 0.35) return mix(1.0, 0.72, (x - 0.0) / 0.35);
  if (x <= 0.7) return mix(0.72, 0.22, (x - 0.35) / 0.35);
  if (x <= 1.0) return mix(0.22, 0.0, (x - 0.7) / 0.30000000000000004);
  return 0.0;
}

void effectMain() {
  vec2 p = vec2(fragPlace.x, uBox.y - fragPlace.y) - 0.5 * uBox;
  float rho = length(p);
  vec3 acc = vec3(0.0);
  float cover = 0.0;
  if (rho > 0.0) {
    float th = atan(p.y, p.x) - uGroup.y;
    float lr = log(rho / uS) - uGroup.x;
    int nMin = max(uRange.x, int(ceil((lr - log(uLens.y)) / uK)));
    int nMax = min(uRange.y, int(floor((lr - log(uLens.x)) / uK)));
    float d = th - (uAlpha * float(nMin) + uTurn0);
    d -= TAU * floor(d / TAU + 0.5);
    float e = exp(lr - uK * float(nMin));
    int s = nMin + uPhase;
    s -= uFlow * int(floor(float(s) / float(uFlow)));
    for (int n = nMin; n <= nMax; n++) {
      if (abs(d) <= uAngMax) {
        float d2 = d * d;
        float cd = 1.0 - d2 * (0.5 - d2 * (0.0416666667 - d2 * 0.0013888889));
        float sd = d * (1.0 - d2 * (0.1666666667 - d2 * (0.0083333333 - d2 * 0.0001984127)));
        float qx = e * cd;
        float qy = e * sd;
        vec2 l = vec2(qx - uLensMid.x, abs(qy) + uLensMid.y);
        float cov = clamp(0.5 - (length(l) - uLens.w) * (rho / e), 0.0, 1.0);
        if (cov > 0.0) {
          vec2 uv = vec2((qx - uLens.x) / (uLens.y - uLens.x), (qy + uLens.z) / (2.0 * uLens.z));
          float w = (1.0 - cover) * cov;
          acc += w * stopColor(uKeyOfSlot[s], length((uv - uGrad.xy) / uGrad.zw));
          cover += w;
          if (cover > 0.99999) break;
        }
      }
      d -= uAlpha;
      if (d < -3.14159265359) d += TAU;
      else if (d > 3.14159265359) d -= TAU;
      e *= uEk;
      s += 1;
      if (s >= uFlow) s = 0;
    }
  }
  vec3 col = acc + (1.0 - cover) * uGround;
  float hr = rho / uS;
  if (hr < uHeartR.y) col = mix(col, uHeart, hr <= uHeartR.x ? 1.0 : heartAlpha((hr - uHeartR.x) / (uHeartR.y - uHeartR.x)));
  o = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  if (state(iChannel0, T_FLAGS).z == 0.0) {
    fragColor = texelFetch(iChannel1, ivec2(fragCoord), 0);
    return;
  }
  fragPlace = vec4(fragCoord, 0.0, 1.0);
  vec4 box = state(iChannel0, T_BOX);
  float one = iResolution.z;
  uBox = box.xy;
  uS = box.z;
  uRange = ivec2(INNERMOST, int(box.w));
  uGroup = state(iChannel0, T_GROUP).xy;
  uK = TURN.x * one;
  uEk = TURN.y * one;
  uAlpha = TURN.z * one;
  uTurn0 = TURN.w * one;
