  c = uint(x <= 0xffffffu); n += c * 8u; x <<= c * 8u;
  c = uint(x <= 0xfffffffu); n += c * 4u; x <<= c * 4u;
  c = uint(x <= 0x3fffffffu); n += c * 2u; x <<= c * 2u;
